"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyToolChips from "../beautiful-ui/primitives/ToolChips";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type ToolChipsProps = NonNullable<ComponentProps<typeof LegacyToolChips>>;

export const ToolChips = forwardRef<HTMLDivElement, ToolChipsProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyToolChips {...props} />
  </BeautifulUIRoot>
));

ToolChips.displayName = "ToolChips";

export default ToolChips;

"use client";

import "../beautiful-ui.css";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "framer-motion";
import { springs } from "@/lib/springs";
import { useShape } from "@/lib/shape-context";
import { useSurface } from "@/lib/surface-context";
import { surfaceClasses } from "@/lib/surface-classes";
import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import { useFluidHover, useRegisterFluidHoverItem } from "@/hooks/use-fluid-hover";
import { BeautifulUIPortalRoot } from "../BeautifulUIRoot";
import { useReducedMotion } from "../hooks/useReducedMotion";

/* ─────────────────────────────────────────────────────────
 * TOOL CHIPS
 * An agent run as compact rows: tool calls with inline
 * chips, then file-diff chips summarizing the edits.
 * Hover a row to reveal its chevron; every row expands
 * to show what the tool actually did.
 * ───────────────────────────────────────────────────────── */

const STEP_MS = 700;

const ToolHoverContext = createContext<ReturnType<typeof useFluidHover> | null>(null);

function FluidToolGroup({
  children,
  axis = "y",
  className,
}: {
  children: ReactNode;
  axis?: "y" | "xy";
  className: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const mouseInside = useRef(false);
  const shape = useShape();
  const hover = useFluidHover(ref, { axis, gapClick: false });

  return (
    <ToolHoverContext.Provider value={hover}>
      <div
        ref={ref}
        className={`relative isolate ${className}`}
        {...hover.handlers}
        onMouseEnter={() => {
          mouseInside.current = true;
          hover.handlers.onMouseEnter();
        }}
        onMouseLeave={() => {
          mouseInside.current = false;
          hover.handlers.onMouseLeave();
          const focused = document.activeElement;
          if (
            focused instanceof HTMLElement &&
            ref.current?.contains(focused) &&
            focused.matches(":focus-visible")
          ) {
            const index = focused.getAttribute("data-tool-hover-index");
            if (index !== null) hover.setActiveIndex(Number(index));
          }
        }}
        onFocusCapture={(event) => {
          const index = (event.target as HTMLElement)
            .closest("[data-tool-hover-index]")
            ?.getAttribute("data-tool-hover-index");
          if (index != null) hover.setActiveIndex(Number(index));
        }}
        onBlurCapture={(event) => {
          if (!ref.current?.contains(event.relatedTarget) && !mouseInside.current) {
            hover.setActiveIndex(null);
          }
        }}
      >
        <FluidHoverHighlight hover={hover} className={shape.item} />
        {children}
      </div>
    </ToolHoverContext.Provider>
  );
}

function FluidToolItem({
  index,
  className,
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & { index: number }) {
  const hover = useContext(ToolHoverContext);
  const ref = useRef<HTMLButtonElement>(null);
  useRegisterFluidHoverItem(hover?.registerItem, index, ref);
  return (
    <button
      ref={ref}
      data-tool-hover-index={index}
      className={`relative z-10 ${className ?? ""}`}
      {...props}
    />
  );
}

const Icons: Record<string, React.ReactNode> = {
  think: <path d="M12 2l2.4 7.2L22 12l-7.6 2.8L12 22l-2.4-7.2L2 12l7.6-2.8z" />,
  write: (
    <g
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M17 3a2.8 2.8 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5z" />
    </g>
  ),
  run: (
    <g
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M4 17l6-5-6-5M12 19h8" />
    </g>
  ),
  read: (
    <g
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
      <path d="M14 2v6h6" />
    </g>
  ),
};

type DetailLine = { text: string; tone?: "add" };

const ROWS: {
  icon: string;
  label: string;
  chip: string;
  mono: boolean;
  detailMono: boolean;
  detail: DetailLine[];
}[] = [
  {
    icon: "think",
    label: "Thinking",
    chip: "Planning the churn schedule…",
    mono: false,
    detailMono: false,
    detail: [
      { text: "Weekend demand carries pistachio, so it churns first." },
      { text: "Batch capacity leaves two evening freezer windows." },
    ],
  },
  {
    icon: "write",
    label: "Write 204 lines",
    chip: "ChurnSchedule.tsx",
    mono: true,
    detailMono: true,
    detail: [
      { text: "+ const windows = slots.filter((s) => s.temp <= -12)", tone: "add" },
      { text: '+ return schedule(windows, { hero: "pistachio" })', tone: "add" },
    ],
  },
  {
    icon: "run",
    label: "Rebuild and verify",
    chip: "npm run freeze",
    mono: true,
    detailMono: true,
    detail: [{ text: "✓ built in 1.2s" }, { text: "✓ 34 checks passed" }],
  },
  {
    icon: "read",
    label: "Read image",
    chip: "flavor-chart.png",
    mono: true,
    detailMono: false,
    detail: [
      { text: "1280 × 720 · line chart, three summers." },
      { text: "Mint chip trends up 12% through July." },
    ],
  },
];

const DIFFS = [
  { file: "flavors.css", add: 13, del: 0 },
  { file: "ChurnSchedule.tsx", add: 74, del: 41 },
  { file: "menu.ts", add: 8, del: 2 },
];

/* hovering a file chip opens its diff — green added, red removed */
type DiffLine = { text: string; tone: "add" | "del" | "ctx" };
const DIFF_LINES: Record<string, DiffLine[]> = {
  "flavors.css": [
    { text: ".scoop-card {", tone: "ctx" },
    { text: "  gap: 14px;", tone: "del" },
    { text: "  gap: 12px;", tone: "add" },
    { text: "  container-type: inline-size;", tone: "add" },
    { text: "}", tone: "ctx" },
  ],
  "ChurnSchedule.tsx": [
    { text: "const slots = coldSlots(week);", tone: "ctx" },
    { text: "const windows = slots;", tone: "del" },
    { text: "const windows = slots.filter(", tone: "add" },
    { text: "  (s) => s.temp <= -12,", tone: "add" },
    { text: ");", tone: "add" },
  ],
  "menu.ts": [
    { text: 'export const hero = "mint-chip";', tone: "del" },
    { text: 'export const hero = "pistachio";', tone: "add" },
  ],
};

export interface ToolChipsProps {
  demo?: boolean;
  onToolToggle?: (tool: string, expanded: boolean) => void;
  onPreviewChange?: (file: string | null) => void;
  onComplete?: () => void;
}

export default function ToolChips({
  demo = false,
  onToolToggle,
  onPreviewChange,
  onComplete,
}: ToolChipsProps) {
  const shape = useShape();
  const surface = useSurface();
  const reducedMotion = useReducedMotion();
  const [step, setStep] = useState(0);
  const [open, setOpen] = useState(true);
  const [openRows, setOpenRows] = useState<Set<string>>(new Set());
  const completedRef = useRef(false);
  const previewId = useId();
  /* Rendered in a body portal so animated/translated reply wrappers cannot
   * redefine the fixed-position coordinate system. */
  const [preview, setPreview] = useState<{
    file: string;
    x: number;
    top?: number;
    bottom?: number;
  } | null>(null);
  const dismissPreview = () => {
    if (!preview) return;
    setPreview(null);
    onPreviewChange?.(null);
  };
  const openPreview = (file: string) => (event: React.SyntheticEvent) => {
    const rect = (event.currentTarget as Element)
      .closest("[data-diffchip]")!
      .getBoundingClientRect();
    const previewHeight = 38 + (DIFF_LINES[file]?.length ?? 0) * 19;
    const fitsBelow = rect.bottom + 6 + previewHeight <= window.innerHeight - 12;
    const next = {
      file,
      x: Math.max(12, Math.min(rect.left, window.innerWidth - 300)),
      ...(fitsBelow ? { top: rect.bottom + 6 } : { bottom: window.innerHeight - rect.top + 6 }),
    };
    setPreview(next);
    onPreviewChange?.(file);
  };
  const closePreview = (file: string) => () => {
    if (preview?.file !== file) return;
    dismissPreview();
  };
  const total = ROWS.length + 1; // rows, then diff chips

  useEffect(() => {
    if (reducedMotion || !demo) {
      setStep(total);
      return;
    }
    if (step >= total) return;
    const t = setTimeout(() => setStep((s) => s + 1), STEP_MS);
    return () => clearTimeout(t);
  }, [demo, reducedMotion, step, total]);

  useEffect(() => {
    if (step < total || completedRef.current) return;
    completedRef.current = true;
    onComplete?.();
  }, [onComplete, step, total]);

  useEffect(() => {
    if (!preview) return;
    const dismiss = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      setPreview(null);
      onPreviewChange?.(null);
    };
    document.addEventListener("keydown", dismiss);
    return () => document.removeEventListener("keydown", dismiss);
  }, [onPreviewChange, preview]);

  const toggleRow = (label: string) => {
    const expanded = !openRows.has(label);
    setOpenRows((current) => {
      const next = new Set(current);
      if (expanded) next.add(label);
      else next.delete(label);
      return next;
    });
    onToolToggle?.(label, expanded);
  };

  return (
    <div className="min-h-[220px] w-full max-w-80 pb-1">
      {/* collapsed run header */}
      <button
        type="button"
        aria-expanded={open}
        aria-label={`${open ? "Collapse" : "Expand"} tool run details`}
        onClick={() => {
          const next = !open;
          setOpen(next);
          if (!next) dismissPreview();
        }}
        className={`-mx-1.5 flex w-fit items-center gap-1.5 ${shape.button} px-1.5 py-1 text-[13px] text-[var(--ink-2)] transition-[background-color,transform] duration-80 hover:bg-[var(--hover-2)] active:scale-[0.98]`}
      >
        <svg
          width="12"
          height="12"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="transition-transform duration-160"
          style={{ transform: open ? "rotate(0deg)" : "rotate(-90deg)" }}
        >
          <path d="M6 9l6 6 6-6" />
        </svg>
        <span className="tabular-nums">4 tool calls, 2 messages</span>
      </button>

      <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {step >= total ? "Tool run complete" : ""}
      </span>

      {/* Collapsed rows leave the accessibility tree and tab order. */}
      {open && (
        <div>
          {/* -mx-1 + px-1.5 keeps content at the same x while giving the
            row hover pills room inside this overflow-hidden clip box */}
          <div className="-mx-1 overflow-hidden px-1.5 pb-1">
            <FluidToolGroup className="mt-1.5 flex flex-col gap-1">
              {ROWS.slice(0, step).map((row, index) => {
                const rowOpen = openRows.has(row.label);
                return (
                  <div
                    key={row.label}
                    style={{
                      animation: reducedMotion
                        ? "none"
                        : "fade-up 240ms cubic-bezier(0.23,1,0.32,1) both",
                    }}
                  >
                    <FluidToolItem
                      index={index}
                      type="button"
                      aria-expanded={rowOpen}
                      aria-label={`${rowOpen ? "Collapse" : "Expand"} ${row.label} details`}
                      onClick={() => toggleRow(row.label)}
                      className={`group/row -mx-[3px] flex h-7 w-[calc(100%+6px)] min-w-0 items-center gap-2 ${shape.item} px-[3px] text-left transition-transform duration-80 active:scale-[0.98]`}
                    >
                      <span className="relative flex size-4 shrink-0 items-center justify-center text-[var(--ink-3)]">
                        <svg
                          width="13"
                          height="13"
                          viewBox="0 0 24 24"
                          fill={row.icon === "think" ? "currentColor" : "none"}
                          stroke="currentColor"
                          className={`transition-opacity duration-80 group-data-[fluid-hover-active]/row:opacity-0 ${rowOpen ? "opacity-0" : ""}`}
                        >
                          {Icons[row.icon]}
                        </svg>
                        <svg
                          width="12"
                          height="12"
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2.2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          className={`absolute transition-[opacity,transform] duration-80 group-data-[fluid-hover-active]/row:opacity-100 ${rowOpen ? "opacity-100" : "opacity-0"}`}
                          style={{ transform: rowOpen ? "rotate(0deg)" : "rotate(-90deg)" }}
                        >
                          <path d="M6 9l6 6 6-6" />
                        </svg>
                      </span>
                      <span className="shrink-0 text-[13px] font-medium text-[var(--ink)]">
                        {row.label}
                      </span>
                      <span
                        className={`inline-flex h-5.5 min-w-0 flex-1 cursor-pointer items-center truncate ${shape.item} ${surfaceClasses(surface, 1)} px-1.5
                    text-[12px] text-[var(--ink-2)]
                    ${row.mono ? "font-mono" : ""}`}
                      >
                        {row.chip}
                      </span>
                    </FluidToolItem>

                    {/* expanded detail */}
                    <AnimatePresence initial={false}>
                      {rowOpen && (
                        <motion.div
                          initial={reducedMotion ? false : { height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          transition={reducedMotion ? { duration: 0 } : springs.slow}
                          className="overflow-hidden"
                        >
                          <div className="mt-0.5 mb-1 ml-2 flex flex-col gap-0.5 border-l border-[var(--line)] py-0.5 pl-3.5">
                            {row.detail.map((line) => (
                              <span
                                key={line.text}
                                className={`truncate text-[12px] leading-[1.6] ${row.detailMono ? "font-mono" : ""} ${line.tone === "add" ? "text-[var(--green)]" : "text-[var(--ink-2)]"}`}
                              >
                                {line.text}
                              </span>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                );
              })}
            </FluidToolGroup>

            {/* file-diff chips */}
            {step >= total && (
              <FluidToolGroup
                axis="xy"
                className="mt-2.5 flex max-w-full flex-wrap gap-1.5 border-t border-[var(--line)] pt-2.5"
              >
                {DIFFS.map((d, i) => (
                  <span
                    key={d.file}
                    data-diffchip
                    className="relative inline-flex"
                    onMouseEnter={openPreview(d.file)}
                    onMouseLeave={closePreview(d.file)}
                  >
                    <span
                      aria-hidden
                      className={`pointer-events-none absolute inset-0 -z-10 ${shape.button} ${surfaceClasses(surface, 2)}`}
                    />
                    <FluidToolItem
                      index={i}
                      type="button"
                      aria-expanded={preview?.file === d.file}
                      aria-label={`Show diff for ${d.file}`}
                      aria-describedby={preview?.file === d.file ? previewId : undefined}
                      onFocus={openPreview(d.file)}
                      onBlur={closePreview(d.file)}
                      onKeyDown={(event) => {
                        if (event.key !== "Escape") return;
                        event.preventDefault();
                        event.stopPropagation();
                        closePreview(d.file)();
                      }}
                      className={`inline-flex h-7 max-w-full items-center gap-1.5 ${shape.button}
                  bg-transparent px-2 font-mono text-[12px] text-[var(--ink)]
                  transition-transform duration-80 active:scale-[0.98]`}
                      style={{
                        animation: reducedMotion
                          ? "none"
                          : `pop-in 240ms cubic-bezier(0.23,1,0.32,1) ${i * 80}ms both`,
                      }}
                    >
                      <span className="min-w-0 truncate">{d.file}</span>
                      <span className="shrink-0 text-[var(--green)] tabular-nums">+{d.add}</span>
                      {d.del > 0 && (
                        <span className="shrink-0 text-[var(--red)] tabular-nums">−{d.del}</span>
                      )}
                    </FluidToolItem>
                  </span>
                ))}
              </FluidToolGroup>
            )}
          </div>
        </div>
      )}
      {preview &&
        typeof document !== "undefined" &&
        createPortal(
          <BeautifulUIPortalRoot
            id={previewId}
            role="tooltip"
            className={`pointer-events-none fixed z-50 w-72 overflow-hidden ${shape.container} ${surfaceClasses(Math.min(surface + 2, 8), 3)} text-[var(--ink)]`}
            style={{
              left: preview.x,
              top: preview.top,
              bottom: preview.bottom,
              animation: reducedMotion ? "none" : "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
              transformOrigin: preview.top === undefined ? "bottom left" : "top left",
            }}
          >
            <div className="flex items-center justify-between border-b border-[var(--line)] px-3 py-2 font-mono text-[12px]">
              <span className="min-w-0 truncate text-[var(--ink-2)]">{preview.file}</span>
              <span className="shrink-0 tabular-nums">
                <span className="text-[var(--green)]">
                  +{DIFFS.find((diff) => diff.file === preview.file)?.add}
                </span>
                {(DIFFS.find((diff) => diff.file === preview.file)?.del ?? 0) > 0 && (
                  <span className="text-[var(--red)]">
                    {" "}
                    −{DIFFS.find((diff) => diff.file === preview.file)?.del}
                  </span>
                )}
              </span>
            </div>
            <div className="py-1 font-mono text-[12px] leading-[1.7]">
              {(DIFF_LINES[preview.file] ?? []).map((line, index) => (
                <div
                  key={index}
                  className={`flex gap-2 px-2.5 whitespace-pre ${
                    line.tone === "add"
                      ? "bg-[var(--green-tint)] text-[var(--green)]"
                      : line.tone === "del"
                        ? "bg-[var(--red-tint)] text-[var(--red)]"
                        : "text-[var(--ink-2)]"
                  }`}
                >
                  <span className="w-3 shrink-0 select-none">
                    {line.tone === "add" ? "+" : line.tone === "del" ? "−" : " "}
                  </span>
                  <span className="min-w-0 truncate">{line.text}</span>
                </div>
              ))}
            </div>
          </BeautifulUIPortalRoot>,
          document.body,
        )}
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

